import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

constexpr int TILE_TH = 8;
constexpr int TILE_TW = 16;
constexpr int CIN_CHUNK = 8;
__global__ void conv_transpose3d_tiled_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ y,
    int B, int Cin, int Cout,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    int Kd, int Kh, int Kw,
    int pd, int ph, int pw)
{
    extern __shared__ float xs[];
    const int Kvol = Kd * Kh * Kw;
    const int SH = TILE_TH + Kh - 1;
    const int SW = TILE_TW + Kw - 1;
    const int num_w = (Wout + TILE_TW - 1) / TILE_TW;
    const int num_h = (Hout + TILE_TH - 1) / TILE_TH;
    int t = blockIdx.x;
    const int ow_tile = t % num_w; t /= num_w;
    const int oh_tile = t % num_h; t /= num_h;
    const int od = t % Dout;
    const int n = t / Dout;
    const int tx = threadIdx.x;
    const int ow_l = tx % TILE_TW;
    const int oh_l = tx / TILE_TW;
    const int ow = ow_tile * TILE_TW + ow_l;
    const int oh = oh_tile * TILE_TH + oh_l;
    const bool active = (oh < Hout) && (ow < Wout);
    const int id0 = od + pd - Kd + 1;
    const int ih0 = oh_tile * TILE_TH + ph - Kh + 1;
    const int iw0 = ow_tile * TILE_TW + pw - Kw + 1;
    for (int co0 = 0; co0 < Cout; co0 += 16) {
        const int rem = min(16, Cout - co0);
        float acc[16];
        #pragma unroll
        for (int lane = 0; lane < 16; ++lane) acc[lane] = 0.0f;
        for (int ci0 = 0; ci0 < Cin; ci0 += CIN_CHUNK) {
            const int remc = min(CIN_CHUNK, Cin - ci0);
            const int tile_elems = remc * Kd * SH * SW;
            for (int idx = tx; idx < tile_elems; idx += blockDim.x) {
                int ww = idx % SW;
                int q = idx / SW;
                int hh = q % SH;
                q /= SH;
                int dd = q % Kd;
                int cc = q / Kd;
                const int id = id0 + dd;
                const int ih = ih0 + hh;
                const int iw = iw0 + ww;
                float v = 0.0f;
                if (id >= 0 && id < Din && ih >= 0 && ih < Hin && iw >= 0 && iw < Win) {
                    v = x[((((size_t)n * Cin + ci0 + cc) * Din + id) * Hin + ih) * Win + iw];
                }
                xs[idx] = v;
            }
            __syncthreads();
            if (active) {
                for (int c = 0; c < remc; ++c) {
                    const int ci = ci0 + c;
                    for (int kd = 0; kd < Kd; ++kd) {
                        const int dd = Kd - 1 - kd;
                        for (int kh = 0; kh < Kh; ++kh) {
                            const int hh = Kh - 1 - kh + oh_l;
                            for (int kw = 0; kw < Kw; ++kw) {
                                const int ww = Kw - 1 - kw + ow_l;
                                const float xv = xs[((c * Kd + dd) * SH + hh) * SW + ww];
                                const float* wk = w + ((((size_t)ci * Cout + co0) * Kd + kd) * Kh + kh) * Kw + kw;
                                #pragma unroll
                                for (int lane = 0; lane < 16; ++lane) {
                                    if (lane < rem) acc[lane] += xv * wk[(size_t)lane * Kvol];
                                }
                            }
                        }
                    }
                }
            }
            __syncthreads();
        }
        if (active) {
            #pragma unroll
            for (int lane = 0; lane < 16; ++lane) {
                if (lane < rem) {
                    const int co = co0 + lane;
                    const float b = bias ? bias[co] : 0.0f;
                    y[((((size_t)n * Cout + co) * Dout + od) * Hout + oh) * Wout + ow] = acc[lane] + b;
                }
            }
        }
    }
}
__global__ void conv_transpose3d_single_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ y,
    int B, int Cin, int Cout,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    int Kd, int Kh, int Kw,
    int sd, int sh, int sw,
    int pd, int ph, int pw,
    int groups,
    long long total_spatial,
    long long total_elems)
{
    const long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    if (tid >= total_elems) return;
    long long t = tid;
    const int ow = (int)(t % Wout); t /= Wout;
    const int oh = (int)(t % Hout); t /= Hout;
    const int od = (int)(t % Dout); t /= Dout;
    const int co = (int)(t % Cout); t /= Cout;
    const int n  = (int)t;
    const int out_per = Cout / groups;
    const int in_per  = Cin / groups;
    const int g       = co / out_per;
    const int co_rel  = co - g * out_per;
    const int ci0     = g * in_per;
    const int ci1     = ci0 + in_per;
    float sum = bias ? bias[co] : 0.0f;
    for (int ci = ci0; ci < ci1; ++ci) {
        for (int kd = 0; kd < Kd; ++kd) {
            const int nd = od + pd - kd;
            if (nd < 0 || (nd % sd) != 0) continue;
            const int id = nd / sd;
            if (id < 0 || id >= Din) continue;
            for (int kh = 0; kh < Kh; ++kh) {
                const int nh = oh + ph - kh;
                if (nh < 0 || (nh % sh) != 0) continue;
                const int ih = nh / sh;
                if (ih < 0 || ih >= Hin) continue;
                for (int kw = 0; kw < Kw; ++kw) {
                    const int nw = ow + pw - kw;
                    if (nw < 0 || (nw % sw) != 0) continue;
                    const int iw = nw / sw;
                    if (iw < 0 || iw >= Win) continue;
                    const float xv = x[((((size_t)n * Cin + ci) * Din + id) * Hin + ih) * Win + iw];
                    const float wv = w[((((size_t)ci * out_per + co_rel) * Kd + kd) * Kh + kh) * Kw + kw];
                    sum += xv * wv;
                }
            }
        }
    }
    y[((((size_t)n * Cout + co) * Dout + od) * Hout + oh) * Wout + ow] = sum;
}
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int64_t sd, int64_t sh, int64_t sw,
    int64_t pd, int64_t ph, int64_t pw,
    int64_t od, int64_t oh, int64_t ow,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda());
    TORCH_CHECK(weight.is_cuda());
    TORCH_CHECK(x.scalar_type() == at::kFloat);
    TORCH_CHECK(weight.scalar_type() == at::kFloat);
    TORCH_CHECK(x.dim() == 5);
    TORCH_CHECK(weight.dim() == 5);
    x = x.contiguous();
    weight = weight.contiguous();
    if (has_bias) {
        TORCH_CHECK(bias.is_cuda());
        TORCH_CHECK(bias.scalar_type() == at::kFloat);
        bias = bias.contiguous();
    }
    const int B   = (int)x.size(0);
    const int Cin = (int)x.size(1);
    const int Din = (int)x.size(2);
    const int Hin = (int)x.size(3);
    const int Win = (int)x.size(4);
    const int Kd = (int)weight.size(2);
    const int Kh = (int)weight.size(3);
    const int Kw = (int)weight.size(4);
    TORCH_CHECK(weight.size(0) == Cin);
    TORCH_CHECK(Cin % groups == 0);
    const int Cout = (int)weight.size(1) * (int)groups;
    if (has_bias) TORCH_CHECK(bias.numel() == Cout);
    const int Dout = (int)((Din - 1) * sd - 2 * pd + Kd + od);
    const int Hout = (int)((Hin - 1) * sh - 2 * ph + Kh + oh);
    const int Wout = (int)((Win - 1) * sw - 2 * pw + Kw + ow);
    auto y = at::empty({B, Cout, Dout, Hout, Wout}, x.options());
    const long long total_spatial = (long long)B * Dout * Hout * Wout;
    const long long total_elems   = total_spatial * Cout;
    if (total_elems == 0) return y;
    const float* bias_ptr = has_bias ? bias.data_ptr<float>() : nullptr;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    const int SH = TILE_TH + Kd * 0 + Kh - 1;
    const int SW = TILE_TW + Kw - 1;
    const size_t smem_bytes = (size_t)CIN_CHUNK * Kd * SH * SW * sizeof(float);
    const bool use_tiled = (groups == 1) && (sd == 1) && (sh == 1) && (sw == 1) &&
                           (smem_bytes <= 48 * 1024);
    if (use_tiled) {
        const int num_w = (Wout + TILE_TW - 1) / TILE_TW;
        const int num_h = (Hout + TILE_TH - 1) / TILE_TH;
        const long long tiles_ll = (long long)B * Dout * num_h * num_w;
        TORCH_CHECK(tiles_ll <= 2147483647LL);
        const dim3 blocks((unsigned int)tiles_ll);
        conv_transpose3d_tiled_kernel<<<blocks, TILE_TH * TILE_TW, smem_bytes, stream>>>(
            x.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias_ptr,
            y.data_ptr<float>(),
            B, Cin, Cout,
            Din, Hin, Win,
            Dout, Hout, Wout,
            Kd, Kh, Kw,
            (int)pd, (int)ph, (int)pw);
    } else {
        const int threads = 256;
        const long long blocks_ll = (total_elems + threads - 1) / threads;
        TORCH_CHECK(blocks_ll <= 2147483647LL);
        const dim3 blocks((unsigned int)blocks_ll);
        conv_transpose3d_single_kernel<<<blocks, threads, 0, stream>>>(
            x.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias_ptr,
            y.data_ptr<float>(),
            B, Cin, Cout,
            Din, Hin, Win,
            Dout, Hout, Wout,
            Kd, Kh, Kw,
            (int)sd, (int)sh, (int)sw,
            (int)pd, (int)ph, (int)pw,
            (int)groups,
            total_spatial,
            total_elems);
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}
"""

_cpp_src = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int64_t sd, int64_t sh, int64_t sw,
    int64_t pd, int64_t ph, int64_t pw,
    int64_t od, int64_t oh, int64_t ow,
    int64_t groups);
"""

_mod = load_inline(
    name="conv_transpose3d_single_kernel_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1, 1),
        padding: tuple = (0, 0, 0),
        output_padding: tuple = (0, 0, 0),
        groups: int = 1,
        bias: bool = False,
    ):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )
        self.register_buffer("_empty_bias", torch.empty(0), persistent=False)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        b = self.conv_transpose3d.bias
        has_bias = b is not None
        if not has_bias:
            b = self._empty_bias.to(device=x.device, dtype=x.dtype)
        s = self.conv_transpose3d.stride
        p = self.conv_transpose3d.padding
        op = self.conv_transpose3d.output_padding
        return _mod.conv_transpose3d_forward(
            x,
            self.conv_transpose3d.weight,
            b,
            has_bias,
            int(s[0]), int(s[1]), int(s[2]),
            int(p[0]), int(p[1]), int(p[2]),
            int(op[0]), int(op[1]), int(op[2]),
            int(self.conv_transpose3d.groups),
        )

